     3→|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */
     4→
     5→import * as React from 'react';
     6→import { mergeRefs } from '../../../util/reactUtil.ts';
     7→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
     8→import { useScroller } from '../../../layouts/util/Scroller.tsx';
     9→
    10→import { Button } from '../../actions/Button/Button.tsx';
    11→import { IconButton } from '../../actions/IconButton/IconButton.tsx';
    12→import { H5 } from '../../../typography/Heading/Heading.tsx';
    13→import { TooltipProvider } from '../../overlays/Tooltip/TooltipProvider.tsx';
    14→import { Spinner } from '../../graphics/Spinner/Spinner.tsx';
    15→
    16→import cl from './Dialog.module.scss';
    17→
    18→
    19→export { cl as DialogClassNames };
    20→
    21→
    22→export type DialogContext = {
    23→  close: () => void,
    24→};
    25→export const DialogContext = React.createContext<null | DialogContext>(null);
    26→export const useDialogContext = () => {
    27→  const context = React.use(DialogContext);
    28→  if (context === null) { throw new Error(`Cannot read DialogContext: missing provider.`); }
    29→  return context;
    30→};
    31→
    32→
    33→type ActionProps = React.ComponentProps<typeof Button> & {
    34→  /** Optional tooltip text. */
    35→  tooltip?: undefined | ComponentProps<typeof TooltipProvider>['tooltip'],
    36→};
    37→/**
    38→ * An action button to be displayed in the dialog footer.
    39→ */
    40→const Action = ({ tooltip = null, ...buttonProps }: ActionProps) => {
    41→  return (
    42→    <TooltipProvider compact tooltip={typeof tooltip !== 'undefined' ? tooltip : null}>
    43→      <Button
    44→        {...buttonProps}
    45→        className={cx(cl['bk-dialog__action'], buttonProps.className)}
    46→      />
    47→    </TooltipProvider>
    48→  );
    49→};
    50→
    51→type ActionIconProps = React.ComponentProps<typeof IconButton> & {
    52→  /** Optional tooltip text. */
    53→  tooltip?: undefined | ComponentProps<typeof TooltipProvider>['tooltip'],
    54→};
    55→/**
    56→ * An action that is rendered as just an icon.
    57→ */
    58→const ActionIcon = ({ tooltip, ...iconButtonProps }: ActionIconProps) => {
    59→  return (
    60→    <TooltipProvider compact tooltip={typeof tooltip !== 'undefined' ? tooltip : iconButtonProps.label}>
    61→      <IconButton
    62→        {...iconButtonProps}
    63→        className={cx(cl['bk-dialog__action--icon'], iconButtonProps.className)}
    64→      />
    65→    </TooltipProvider>
    66→  );
    67→};
    68→
    69→const CancelAction = (props: ActionProps) => {
    70→  const context = useDialogContext();
    71→  const handlePress = () => { props.onPress?.(); context.close(); };
    72→  return <Action kind="secondary" label="Cancel" {...props} onPress={handlePress}/>;
    73→};
    74→const SubmitAction = (props: ActionProps) => {
    75→  const context = useDialogContext();
    76→  const handlePress = () => { props.onPress?.(); context.close(); };
    77→  return <Action kind="primary" label="Submit" {...props} onPress={handlePress}/>;
    78→};
    79→
    80→export type DialogProps = Omit<ComponentProps<'dialog'>, 'title'> & {
    81→  /** Whether this component should be unstyled. Default: false. */
    82→  unstyled?: undefined | boolean,
    83→  
    84→  /** Whether the dialog should be displayed as a flat panel (no shadows/borders/rounding). Default: false. */
    85→  flat?: undefined | boolean,
    86→  
    87→  /** The title of the dialog, to be displayed in the dialog header. */
    88→  title: React.ReactNode,
    89→    
    90→  /** If specified, a close icon is displayed in the header. Default: true. */
    91→  showCloseIcon?: undefined | boolean,
    92→  
    93→  /** If specified, a close action is displayed in the footer. Default: true. */
    94→  showCancelAction?: undefined | boolean,
    95→
    96→  /** Callback that is called when the user requests the dialog to close. */
    97→  onRequestClose?: undefined | (() => void), // Note: cannot name this `onClose`, dialog already has an `onClose` prop
    98→  
    99→  /** Any additional actions to be shown in the dialog. */
   100→  actions?: undefined | React.ReactNode,
   101→  
   102→  /** Whether to set autofocus on the close button. Default: false. */
   103→  autoFocusClose?: undefined | boolean,
   104→  
   105→  /** Container intended to display an icon on the top left corner, insetting the content and the action buttons. For larger elements, consider using DialogLayout */
   106→  iconAside?: undefined | React.ReactNode,
   107→  
   108→  /** Controls the modal content state to show a loader when in the loading state */
   109→  state?: undefined | 'loading' | 'ready',
   110→};
   111→/**
   112→ * The Dialog component displays an interaction with the user, for example a confirmation, or a form to be submitted.
   113→ */
   114→export const Dialog = Object.assign(
   115→  (props: DialogProps) => {
   116→    const {
   117→      children,
   118→      unstyled = false,
   119→      flat = false,
   120→      title,
   121→      showCloseIcon = true,
   122→      showCancelAction = true,
   123→      onClose,
   124→      onRequestClose,
   125→      actions,
   126→      autoFocusClose = false,
   127→      iconAside,
   128→      state = 'ready',
   129→      ...propsRest
   130→    } = props;
   131→    
   132→    const dialogId = React.useId();
   133→    const dialogRef = React.useRef<HTMLDialogElement>(null);
   134→    const scrollerProps = useScroller(); // FIXME: add `{ hasFocusableChild: true }`?
   135→    
   136→    if ((showCloseIcon || showCancelAction) && typeof onRequestClose !== 'function') {
   137→      console.error(`Missing prop in <Dialog/>: 'onRequestClose' function`);
   138→    }
   139→    
   140→    const dialogContext = React.useMemo<DialogContext>(() => ({
   141→      close: onRequestClose ?? (() => { console.warn('Missing `onRequestClose` callback.'); })
   142→    }), [onRequestClose]);
   143→    
   144→    const handleClose = React.useCallback((event: React.SyntheticEvent<HTMLDialogElement>) => {
   145→      // Workaround for a bug in React where the close event will bubble up to parent components, even though native
   146→      // close events do not bubble.
   147→      event.stopPropagation();
   148→      onClose?.(event);
   149→    }, [onClose]);
   150→    
   151→    return (
   152→      <DialogContext value={dialogContext}>
   153→        <dialog
   154→          open
   155→          //role="dialog" // Default role. Change this to `role="alertdialog"` for things like confirmation modals.
   156→          aria-labelledby={`${dialogId}-title`}
   157→          aria-describedby={`${dialogId}-content`}
   158→          {...scrollerProps}
   159→          {...propsRest}
   160→          ref={mergeRefs(dialogRef, propsRest.ref)}
   161→          className={cx(
   162→            'bk',
   163→            { [cl['bk-dialog']]: !unstyled },
   164→            { [cl['bk-dialog--loading']]: state === 'loading' },
   165→            { [cl['bk-dialog--flat']]: flat },
   166→            { [cl['bk-dialog--icon-aside']]: iconAside },
   167→            scrollerProps.className,
   168→            propsRest.className,
   169→          )}
   170→          onClose={handleClose}
   171→        >
   172→          <header className={cx(cl['bk-dialog__header'])}>
   173→            <H5 id={`${dialogId}-title`} className={cx(cl['bk-dialog__header__title'])}>{title}</H5>
   174→            
   175→            <div className={cx(cl['bk-dialog__header__actions'])}>
   176→              {showCloseIcon &&
   177→                <ActionIcon
   178→                  icon="cross"
   179→                  autoFocus={autoFocusClose}
   180→                  label="Close dialog"
   181→                  tooltip={null}
   182→                  className={cx(cl['bk-dialog__header-action-close'])}
   183→                  onPress={onRequestClose}
   184→                />
   185→              }
   186→            </div>
   187→          </header>
   188→          
   189→          <div className={cl['bk-dialog__content']}>
   190→            {iconAside && (
   191→              <aside className={cx(cl['bk-dialog__content__icon-aside'])}>
   192→                {iconAside}
   193→              </aside>
   194→            )}
   195→            <section
   196→              id={`${dialogId}-content`} // Used with `aria-describedby`
   197→              role="document" // https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/document_role
   198→              // FIXME: make this focusable instead of the <dialog> as per guidelines on MDN?
   199→              //tabIndex={0}
   200→              className={cx(cl['bk-dialog__content__body'], 'bk-prose')}
   201→              inert={state === 'loading'}
   202→            >
   203→              {children}
   204→            </section>
   205→          </div>
   206→
   207→          {state === 'loading' && (
   208→            <div className={cl['bk-dialog__loader']}>
   209→              <Spinner size="medium"/>
   210→            </div>
   211→          )}
   212→
   213→          {(showCancelAction || actions) &&
   214→            <footer className={cx(cl['bk-dialog__actions'])}>
   215→              {showCancelAction && <CancelAction/>}
   216→              {actions}
   217→            </footer>
   218→          }
   219→        </dialog>
   220→      </DialogContext>
   221→    );
   222→  },
   223→  {
   224→    Action,
   225→    ActionIcon,
   226→    CancelAction,
   227→    SubmitAction,
   228→  },
   229→);
   230→

