import type { Meta, StoryObj } from '@storybook/react-vite';
import { Panel } from './Panel';

const meta = {
  title: 'AI Generated/Complex/Panel',
  component: Panel,
} satisfies Meta<typeof Panel>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    children: (
      <>
        <Panel.Heading>Panel Title</Panel.Heading>
        <p>This is the panel content with some text inside.</p>
        <p>Panels are larger containers typically used for main content areas.</p>
      </>
    ),
  },
};

export const WithoutHeading: Story = {
  args: {
    children: (
      <p>Panel content without a heading.</p>
    ),
  },
};

export const Edgeless: Story = {
  args: {
    edgeless: true,
    children: (
      <>
        <Panel.Heading>Edgeless Panel</Panel.Heading>
        <p>This panel has no border or edges.</p>
      </>
    ),
  },
};

export const Unstyled: Story = {
  args: {
    unstyled: true,
    children: (
      <>
        <Panel.Heading>Unstyled Panel</Panel.Heading>
        <p>This panel has no styling applied.</p>
      </>
    ),
  },
};

export const LongContent: Story = {
  args: {
    children: (
      <>
        <Panel.Heading>Panel with Long Content</Panel.Heading>
        <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</p>
        <p>Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.</p>
        <p>Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur.</p>
      </>
    ),
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { Accordion } from './Accordion';
import { Disclosure } from '../Disclosure/Disclosure';

const meta = {
  title: 'AI Generated/Complex/Accordion',
  component: Accordion,
} satisfies Meta<typeof Accordion>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    exclusive: true,
    children: (
      <>
        <Accordion.Item title="Item 1">
          <p>Content for item 1. Only one accordion item can be open at a time in exclusive mode.</p>
        </Accordion.Item>
        <Accordion.Item title="Item 2">
          <p>Content for item 2.</p>
        </Accordion.Item>
        <Accordion.Item title="Item 3">
          <p>Content for item 3.</p>
        </Accordion.Item>
      </>
    ),
  },
};

export const NonExclusive: Story = {
  args: {
    exclusive: false,
    children: (
      <>
        <Accordion.Item title="Item 1">
          <p>In non-exclusive mode, multiple items can be open at the same time.</p>
        </Accordion.Item>
        <Accordion.Item title="Item 2">
          <p>This item can be expanded independently.</p>
        </Accordion.Item>
        <Accordion.Item title="Item 3">
          <p>All items can be open together.</p>
        </Accordion.Item>
      </>
    ),
  },
};

export const Unstyled: Story = {
  args: {
    unstyled: true,
    exclusive: true,
    children: (
      <>
        <Accordion.Item title="Item 1">
          <p>Unstyled accordion item.</p>
        </Accordion.Item>
        <Accordion.Item title="Item 2">
          <p>Another unstyled item.</p>
        </Accordion.Item>
      </>
    ),
  },
};

export const WithLongContent: Story = {
  args: {
    exclusive: true,
    children: (
      <>
        <Accordion.Item title="Expandable Section">
          <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</p>
          <p>Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.</p>
        </Accordion.Item>
        <Accordion.Item title="Another Section">
          <p>Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur.</p>
        </Accordion.Item>
      </>
    ),
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { Dialog } from './Dialog';
import { Icon } from '../../graphics/Icon/Icon';

const meta = {
  title: 'AI Generated/Complex/Dialog',
  component: Dialog,
} satisfies Meta<typeof Dialog>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    title: 'Confirm Action',
    children: (
      <p>Are you sure you want to proceed with this action?</p>
    ),
    onRequestClose: () => alert('Dialog closed'),
    showCloseIcon: true,
    showCancelAction: true,
  },
};

export const WithActions: Story = {
  args: {
    title: 'Delete Item',
    children: (
      <p>This item will be permanently deleted. This action cannot be undone.</p>
    ),
    onRequestClose: () => alert('Dialog closed'),
    showCloseIcon: true,
    showCancelAction: true,
    actions: (
      <Dialog.SubmitAction onPress={() => alert('Item deleted')} />
    ),
  },
};

export const WithIcon: Story = {
  args: {
    title: 'Success',
    children: (
      <p>Your changes have been saved successfully.</p>
    ),
    onRequestClose: () => alert('Dialog closed'),
    showCloseIcon: true,
    showCancelAction: false,
    iconAside: <Icon icon="check" />,
  },
};

export const Loading: Story = {
  args: {
    title: 'Processing',
    children: (
      <p>Please wait while we process your request...</p>
    ),
    onRequestClose: () => alert('Dialog closed'),
    showCloseIcon: false,
    showCancelAction: false,
    state: 'loading',
  },
};

export const CustomContent: Story = {
  args: {
    title: 'User Settings',
    children: (
      <div>
        <p>Update your preferences below:</p>
        <div style={{ marginTop: '1rem' }}>
          <label>
            <input type="checkbox" defaultChecked /> Enable notifications
          </label>
        </div>
        <div style={{ marginTop: '0.5rem' }}>
          <label>
            <input type="checkbox" defaultChecked /> Save preferences
          </label>
        </div>
      </div>
    ),
    onRequestClose: () => alert('Dialog closed'),
    showCloseIcon: true,
    showCancelAction: true,
    actions: (
      <Dialog.SubmitAction onPress={() => alert('Settings saved')} />
    ),
  },
};

